/**
 * Connection diagnostics.
 *
 * Every CRM call is recorded here so the widget can show what it actually asked for and
 * what came back. Two reasons this earns its place rather than being debug cruft:
 *
 *  - "Widget is broken" and "widget works, the query is wrong" look identical from the
 *    outside and are fixed in completely different places. This tells them apart.
 *  - The pool definitions and several api_names are still unconfirmed. When a query
 *    returns zero rows we need to see the query, not just an empty table.
 */

const MAX = 40;

export const diag = {
  org: null,
  user: null,
  framed: false,
  sdkReady: false,
  sdkError: null,
  /**
   * The query params Zoho appends when it loads the widget iframe. The vendored SDK reads
   * `serviceOrigin` from here and passes it straight to postMessage; if it is missing,
   * `new ZSDK` throws "Invalid target origin" and every later ZOHO.CRM.* call dies with
   * "Cannot read properties of undefined (reading 'getContext')". So when the handshake
   * fails, this is the first thing to look at.
   */
  params: null,
  href: null,
  calls: [],
};

export function note(patch) {
  Object.assign(diag, patch);
}

/** Wrap a CRM call: records the query, row count, duration and any error. */
export async function traced(kind, detail, fn) {
  const started = Date.now();
  const entry = { kind, detail, ok: null, rows: null, ms: null, error: null };
  diag.calls.unshift(entry);
  if (diag.calls.length > MAX) diag.calls.length = MAX;
  try {
    const result = await fn();
    entry.ok = true;
    entry.rows = Array.isArray(result) ? result.length : result?.rows?.length ?? null;
    return result;
  } catch (e) {
    entry.ok = false;
    // Zoho errors arrive in several shapes depending on which layer rejected.
    entry.error =
      e?.message ||
      e?.data?.[0]?.message ||
      e?.details?.statusMessage?.message ||
      (typeof e === 'string' ? e : JSON.stringify(e ?? {}).slice(0, 220));
    throw e;
  } finally {
    entry.ms = Date.now() - started;
  }
}

export const summary = () => ({
  ok: diag.calls.filter((c) => c.ok === true).length,
  failed: diag.calls.filter((c) => c.ok === false).length,
  rows: diag.calls.reduce((s, c) => s + (c.rows ?? 0), 0),
});
